<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('roles.manage');verify_csrf();$pdo=staff_db();feature_table($pdo,'roles');feature_table($pdo,'permissions');
if($_SERVER['REQUEST_METHOD']==='POST' && fpost('action')==='toggle'){$role=fint('role_id');$perm=fint('permission_id');$exists=db_one($pdo,'SELECT 1 x FROM role_permissions WHERE role_id=? AND permission_id=?',[$role,$perm]);if($exists)$pdo->prepare('DELETE FROM role_permissions WHERE role_id=? AND permission_id=?')->execute([$role,$perm]);else $pdo->prepare('INSERT INTO role_permissions(role_id,permission_id) VALUES(?,?)')->execute([$role,$perm]);flash('success','Permission updated.');staff_redirect('staff/admin/roles.php?role_id='.$role);}
$roles=db_rows($pdo,'SELECT * FROM roles ORDER BY id');$rid=(int)($_GET['role_id']??($roles[0]['id']??0));$perms=db_rows($pdo,'SELECT p.*,EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_id=? AND rp.permission_id=p.id) enabled FROM permissions p ORDER BY p.permission_key',[$rid]);$pageTitle='Roles & Permissions';require __DIR__.'/../../includes/staff/header.php';module_head('Security','Roles & Permissions','Control which staff roles can view financial, operational and management capabilities.');?>
<section class="staff-panel"><div class="toolbar"><?php foreach($roles as $r):?><a class="btn <?=$rid==$r['id']?'primary':''?>" href="?role_id=<?=$r['id']?>"><?=h($r['name']??$r['role_name']??('Role '.$r['id']))?></a><?php endforeach?></div></section><section class="staff-panel table-panel"><table><thead><tr><th>Permission</th><th>Description</th><th>Enabled</th></tr></thead><tbody><?php foreach($perms as $p):?><tr><td><b><?=h($p['permission_key']??$p['code'])?></b></td><td><?=h($p['description']??$p['name']??'')?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="role_id" value="<?=$rid?>"><input type="hidden" name="permission_id" value="<?=$p['id']?>"><button class="btn <?=$p['enabled']?'primary':''?>"><?=$p['enabled']?'Enabled':'Enable'?></button></form></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>